#include <iostream>
using namespace std;

int main() {
    int a[3] = {10, 20, 30};
    int* p = a;
    cout << *p << endl;
    cout << p[1] << endl;
    cout << *(p + 2) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a[3] = {10, 20, 30};
    for (int* q = a; q != a + 3; q++) {
        cout << *q << " ";
    }
    cout << endl;
    return 0;
}

