bug.fixed:
#include <iostream>
using namespace std;

int count_items(const int a[], int n) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        count += a[i] > 0 ? 1 : 0;
    }
    return count;
}

int main() {
    int a[5] = {1, 2, 3, 4, 5};
    cout << count_items(a, 5) << endl;
    return 0;
}

